# perf_dma_probe_100r_4bg_128.S — DMA bandwidth-latency probe: 4 background channels, 100% loads, 128 B
# Channel 0 times one 32 B load while channels 1..4 stream 128 B
# transfers (100% loads) as background traffic. CSR_DBG1 = (traffic phase
# cycles << 16) | probe cycles; background bytes = 2048.
# Generated by npu-model/scripts/gen_dma_probe_programs.py.
# @TIMEOUT 400000
# @DRAM_BASE 0x90000000
# @PERF_REPORT

    li    x5, 0x00000000
    dma.config x5, ch0
    li    x12, 32
    li    x13, 128
    li    x8, 0
    li    x10, 0x90100000
    li    x1, 2048
    li    x24, 0x90000000
    li    x2, 2304
    li    x25, 0x90000400
    li    x3, 2560
    li    x26, 0x90000800
    li    x4, 2816
    li    x27, 0x90000c00
    csrrs x20, 0xC00, x0        # x20 = traffic phase start
    addi  x0, x0, 0             # keep CSR reads apart
    dma.load  x1, x24, x13, ch1
    dma.load  x2, x25, x13, ch2
    dma.load  x3, x26, x13, ch3
    dma.load  x4, x27, x13, ch4
    csrrs x21, 0xC00, x0        # x21 = probe issue
    dma.load  x8, x10, x12, ch0
    dma.wait  ch0
    csrrs x22, 0xC00, x0        # x22 = probe done
    addi  x0, x0, 0             # keep CSR reads apart
    dma.wait  ch1
    dma.wait  ch2
    dma.wait  ch3
    dma.wait  ch4
    dma.load  x1, x24, x13, ch1
    dma.load  x2, x25, x13, ch2
    dma.load  x3, x26, x13, ch3
    dma.load  x4, x27, x13, ch4
    dma.wait  ch1
    dma.wait  ch2
    dma.wait  ch3
    dma.wait  ch4
    dma.load  x1, x24, x13, ch1
    dma.load  x2, x25, x13, ch2
    dma.load  x3, x26, x13, ch3
    dma.load  x4, x27, x13, ch4
    dma.wait  ch1
    dma.wait  ch2
    dma.wait  ch3
    dma.wait  ch4
    dma.load  x1, x24, x13, ch1
    dma.load  x2, x25, x13, ch2
    dma.load  x3, x26, x13, ch3
    dma.load  x4, x27, x13, ch4
    dma.wait  ch1
    dma.wait  ch2
    dma.wait  ch3
    dma.wait  ch4
    csrrs x23, 0xC00, x0        # x23 = traffic phase end
    sub   x22, x22, x21         # probe cycles
    sub   x23, x23, x20         # traffic phase cycles
    slli  x23, x23, 16
    or    x22, x22, x23
    csrrw x0,  0xC11, x22       # stash in CSR_DBG1
    addi  x30, x0, 1
    csrrw x0, 0xC10, x30
    ecall
